    "campaignsList": [[{"id":"vY4u9BdlwvRL3Un05ZQR","name":"Women’s shoes Size Chart","status":true,"displayType":"AUTOMATED","priority":0,"createdAt":"2026-02-18T20:11:32.041Z","updatedAt":"2026-07-18T17:32:41.343Z","contentConfigs":[{"value":"\u003cp style=\"font-weight: 600; font-size: 1.8rem; text-align: center; line-height: 1.1;\">Women’s shoes Size Chart\u003c/p>"},{"value":"","tableData":{"columns":[{"id":"col3","name":"US Size","type":"key","order":0},{"id":"col2","name":"UK Size","type":"value","order":1},{"id":"col1","name":"EU Size","type":"value","order":2},{"id":"col4","name":"Foot Length (cm)","type":"value","order":3},{"id":"col5","name":"Foot Length (Inch)","order":4,"type":"value"}],"rows":[{"id":"row1","order":0,"col1":"35","col2":"2","col3":"4","col4":"21.6 – 22.0","col5":"8.50-8.66"},{"id":"row2","order":1,"col1":"36","col2":"3","col3":"5","col4":"22.1 – 22.5","col5":"8.70-8.86"},{"id":"row3","order":2,"col1":"37","col2":"4","col3":"6","col4":"22.6 – 23.0","col5":"8.90-9.06"},{"id":"row4","order":3,"col1":"38","col2":"5","col3":"7","col4":"23.1 – 23.5","col5":"9.10-9.26"},{"id":"row5","order":4,"col1":"39","col2":"6","col3":"8","col4":"23.6 – 24.0","col5":"9.30-9.45"},{"id":"row6","order":5,"col1":"40","col2":"7","col3":"9","col4":"24.1 – 24.5","col5":"9.49-9.65"},{"id":"row7","order":6,"col1":"41","col2":"8","col3":"10","col4":"24.6 – 25.0","col5":"9.69-9.84"},{"id":"row8","order":7,"col1":"42","col2":"9","col3":"11","col4":"25.1 – 25.5","col5":"9.89-10.04"},{"id":"row9","order":8,"col1":"43","col2":"10","col3":"12","col4":"25.6 – 26.0","col5":"10.08-10.23"}],"isConvertUnit":false,"defaultUnit":"Centimeter","sizeRange":"columns"},"typeConfig":"advanced_table","tableId":1771442719638},{"value":"","imgSrc":"https://firebasestorage.googleapis.com/v0/b/avada-size-chart-stag.appspot.com/o/charts_content%2F4hHyREkCY9Q2c5Nmhuj0%2F1746696661176-image%2012.png?alt=media&token=071854c9-3044-4324-a93d-bdd3bc6e2519","typeConfig":"image"},{"value":"\u003cp style=\"font-style: normal;font-weight: 650;line-height: 20px;\">How to Measure:\u003c/p>\u003col style=\"padding-inline-start: 15px;\">\u003cli>Place a sheet of paper on a hard floor.\u003c/li>\u003cli>Stand straight with your heel against the wall.\u003c/li>\u003cli>Mark the longest toe on the paper.\u003c/li>\u003cli>Measure the distance from the wall to the toe mark in centimeters.\u003c/li>\u003cli>Use the chart above to find your size.\u003c/li>\u003c/ol>\u003cp style=\"font-style: normal;font-weight: 450;line-height: 20px;\">💡\u003cspan style=\"font-style: italic;\">Tip: Always measure both feet – choose the larger length if there's a difference. For sports shoes, you may want to add 0.5 cm for comfort.\u003c/span>\u003c/p>"}],"sizeRecommend":{"type":"ai","sourceTable":"","measurement":{"select":[],"type":"bodyMeasurement","fitPreference":true,"primary":"","havePrimary":false,"extra":{"unit":"Centimeter","value":6}},"productInfo":{"type":"","fit":{"defaultGarment":"regular","defaultSizeRuns":"true"}}},"conditions":{"type":"ANY","conditions":[{"type":"COLLECTION","operation":"EQUALS","value":"659741180242"},{"type":"COLLECTION","operation":"EQUALS","value":"660224541010"},{"type":"COLLECTION","operation":"EQUALS","value":"660225524050"},{"type":"COLLECTION","operation":"EQUALS","value":"660225720658"}]},"countries_all":true},{"id":"KVTHQMHuBrXat20Wv2Rg","name":"Women’s Bottom Size Chart","status":true,"displayType":"AUTOMATED","priority":0,"createdAt":"2026-02-18T19:40:28.702Z","updatedAt":"2026-07-18T17:32:46.813Z","contentConfigs":[{"value":"\u003cp style=\"font-weight: 600; font-size: 1.8rem; text-align: center; line-height: 1.1;\">Women’s Bottom Size Chart\u003c/p>"},{"value":"","typeConfig":"tab_layout","tabs":[{"name":"Size chart","contentConfigs":[{"value":"","typeConfig":"advanced_table","tableData":{"columns":[{"id":"col1","name":"Size","type":"key","order":0},{"id":"col2","name":"Waist","type":"value","order":1},{"id":"col3","name":"Hip","type":"value","order":2}],"rows":[{"id":"row1","order":0,"col1":"XXS","col2":"58 - 61","col3":"82 - 85"},{"id":"row2","order":1,"col1":"XS","col2":"62 - 65","col3":"86 - 89"},{"id":"row3","order":2,"col1":"S","col2":"66 - 69","col3":"90 - 93"},{"id":"row4","order":3,"col1":"M","col2":"70 - 73","col3":"94 - 97"},{"id":"row5","order":4,"col1":"L","col2":"74 - 77","col3":"98 - 101"},{"id":"row6","order":5,"col1":"XL","col2":"78 - 81","col3":"102 - 105"},{"id":"row7","order":6,"col1":"XXL","col2":"82 - 87","col3":"106 - 111"},{"id":"row8","order":7,"col1":"3XL","col2":"88 - 93","col3":"112 - 117"}],"isConvertUnit":true,"defaultUnit":"Centimeter","sizeRange":"columns"},"tableId":1771442719262}]},{"name":"How to measure","contentConfigs":[{"value":"","imgSrc":"https://firebasestorage.googleapis.com/v0/b/avada-size-chart-stag.appspot.com/o/charts_content%2F4hHyREkCY9Q2c5Nmhuj0%2F1746693093945-image%206.png?alt=media&token=3c6974b7-5888-4a56-b570-fe48d1dc4bd3","typeConfig":"image"},{"value":"\u003cp style=\"font-style: normal;font-weight: 650;line-height: 20px;\">Measurement Guide\u003c/p>\u003cp style=\"font-style: normal;font-weight: 450;line-height: 20px;\">💡\u003cspan style=\"font-style: italic;\">Pro Tip: For bottoms like leggings or fitted skirts, waist size is most important. For jeans or pants, both waist and hip need to be accurate for best fit.\u003c/span>\u003c/p>\u003cul style=\"margin-block-start: 0;\">\u003cli>Waist: Measure around the narrowest part of your waist (usually above the navel).\u003c/li>\u003cli>Hip: Measure around the fullest part of your buttocks/hips, keeping the tape horizontal.\u003c/li>\u003c/ul>"},{"value":"\u003cp style=\"font-style: normal;font-weight: 650;line-height: 20px;\">Fit Notes Based on Body Shape\u003c/p>\u003cul>\u003cli>Pear-shaped: Go by hip size, adjust waist with a belt\u003c/li>\u003cli>Apple-shaped: Choose high-waisted for tummy support\u003c/li>\u003cli>Hourglass: Stretch fabrics or contoured waistbands\u003c/li>\u003cli>Petite (<160 cm): Cropped or short inseams recommended\u003c/li>\u003cli>Tall (>175 cm): Look for tall or long-fit bottom styles\u003c/li>\u003c/ul>"}]}]}],"sizeRecommend":{"type":"ai","sourceTable":"","measurement":{"select":[],"type":"bodyMeasurement","fitPreference":true,"primary":"","havePrimary":false,"extra":{"unit":"Centimeter","value":6}},"productInfo":{"type":"","fit":{"defaultGarment":"regular","defaultSizeRuns":"true"}}},"conditions":{"type":"ANY","conditions":[{"type":"COLLECTION","operation":"EQUALS","value":"659743736146"},{"type":"COLLECTION","operation":"EQUALS","value":"673361887570"}]},"countries_all":true},{"id":"cK8KnGN3LX5WsZjFbEAG","name":"Women’s Top Size Chart","status":true,"displayType":"AUTOMATED","priority":0,"createdAt":"2026-02-18T19:29:35.547Z","updatedAt":"2026-07-18T17:32:59.858Z","contentConfigs":[{"value":"\u003cp style=\"font-weight: 600; font-size: 1.8rem; text-align: center; line-height: 1.1;\">Women’s Top Size Chart\u003c/p>"},{"value":"","typeConfig":"tab_layout","tabs":[{"name":"Size chart","contentConfigs":[{"value":"","typeConfig":"advanced_table","tableData":{"columns":[{"id":"col1","name":"Size","type":"key","order":0},{"id":"col2","name":"Bust","type":"value","order":1},{"id":"col3","name":"Waist","type":"value","order":2},{"id":"col4","name":"Hip","type":"value","order":3}],"rows":[{"id":"row1","order":0,"col1":"XXS","col2":"76 - 79","col3":"58 - 61","col4":"82 - 85"},{"id":"row2","order":1,"col1":"XS","col2":"80 - 83","col3":"62 - 65","col4":"86 - 89"},{"id":"row3","order":2,"col1":"S","col2":"84 - 87","col3":"66 - 69","col4":"90 - 93"},{"id":"row4","order":3,"col1":"M","col2":"88 - 91","col3":"70 - 73","col4":"94 - 97"},{"id":"row5","order":4,"col1":"L","col2":"92 - 95","col3":"74 - 77","col4":"98 - 101"},{"id":"row6","order":5,"col1":"XL","col2":"96 - 99","col3":"78 - 81","col4":"102 - 105"},{"id":"row7","order":6,"col1":"XXL","col2":"100 - 105","col3":"82 - 87","col4":"106 - 111"},{"id":"row8","order":7,"col1":"3XL","col2":"106 - 111","col3":"88 - 93","col4":"112 - 117"}],"isConvertUnit":true,"defaultUnit":"Centimeter","sizeRange":"columns"},"tableId":1771442719176},{"value":"\u003cp style=\"font-style: normal;font-weight: 450;line-height: 20px;\"> Our Women's Top Size Chart serves as your essential guide to finding perfectly fitted garments every time you shop. With detailed bust, waist, and hip measurements across standard sizing categories, this chart eliminates the frustration of returns due to improper fit. Whether shopping in-store or online, consulting this size chart ensures you'll select tops that flatter your unique body shape while providing the comfort and confidence you deserve.\u003c/p>"}]},{"name":"How to measure","contentConfigs":[{"value":"","imgSrc":"https://firebasestorage.googleapis.com/v0/b/avada-size-chart-stag.appspot.com/o/charts_content%2F4hHyREkCY9Q2c5Nmhuj0%2F1746692210794-minimalist-t-shirt-size-chart-template-with-photo%201.png?alt=media&token=86e86b3f-c82c-495c-aaab-1516bbf759fa","typeConfig":"image"},{"value":"\u003cp style=\"font-style: normal;font-weight: 650;line-height: 20px;\">Measurement Guide\u003c/p>\u003cp style=\"font-style: normal;font-weight: 450;line-height: 20px;\">💡\u003cspan style=\"font-style: italic;\">Tip: Wear a non-padded bra when measuring bust for accuracy. Always measure while standing straight, relaxed.\u003c/span>\u003c/p>\u003cul>\u003cli>Bust: Measure around the fullest part of the chest, keeping the tape comfortably snug.\u003c/li>\u003cli>Waist: Measure around the narrowest part of your waist (usually above the navel).\u003c/li>\u003cli>Hip: Measure around the fullest part of the hips and buttocks.\u003c/li>\u003c/ul>"},{"value":"\u003cp style=\"font-style: normal;font-weight: 650;line-height: 20px;\">Fit Notes Based on Body Shape\u003c/p>\u003cul>\u003cli>Petite ( <160 cm): Choose slim or cropped fit styles\u003c/li>\u003cli>Full bust: Size up or look for stretch fabrics\u003c/li>\u003cli>Broad shoulders: Avoid tight sleeves – choose relaxed cuts\u003c/li>\u003cli>Long torso: Look for longer tops or high-waist bottoms\u003c/li>\u003c/ul>"}]}]}],"sizeRecommend":{"type":"ai","sourceTable":"","measurement":{"select":[],"type":"bodyMeasurement","fitPreference":true,"primary":"","havePrimary":false,"extra":{"unit":"Centimeter","value":6}},"productInfo":{"type":"","fit":{"defaultGarment":"regular","defaultSizeRuns":"true"}}},"conditions":{"type":"ANY","conditions":[{"type":"COLLECTION","operation":"EQUALS","value":"659741475154"},{"type":"COLLECTION","operation":"EQUALS","value":"659741540690"},{"type":"COLLECTION","operation":"EQUALS","value":"659741638994"},{"type":"COLLECTION","operation":"EQUALS","value":"660225884498"},{"type":"COLLECTION","operation":"EQUALS","value":"660225950034"},{"type":"COLLECTION","operation":"EQUALS","value":"673362444626"}]},"countries_all":true},{"id":"h1Pqbriu5YWH7OmxQ3vD","name":"Men's Bottom Size Chart","status":true,"displayType":"AUTOMATED","priority":0,"createdAt":"2026-02-18T19:22:24.861Z","updatedAt":"2026-07-18T17:33:15.839Z","contentConfigs":[{"value":"\u003cp style=\"font-weight: 600; text-align: center; line-height: 1.1; font-size: 1.8rem;\">\u003cspan style=\"font-size: 14px;\">Grand Lumaire\u003c/span>\u003c/p>\u003cp style=\"font-weight: 600; text-align: center; line-height: 1.1; font-size: 1.8rem;\">Men's Bottom Size Chart\u003c/p>"},{"value":"","tableData":{"columns":[{"id":"col1","name":"Size","type":"key","order":0},{"id":"col2","name":"Waist","type":"value","order":1},{"id":"col3","name":"Hip","type":"value","order":2},{"id":"col4","name":"Inseam","type":"value","order":3}],"rows":[{"id":"row1","order":0,"col1":"S","col2":"71 - 76","col3":"86 - 91","col4":"76 - 78"},{"id":"row2","order":1,"col1":"M","col2":"77 - 84","col3":"92 - 99","col4":"81 - 84"},{"id":"row3","order":2,"col1":"L","col2":"85 - 91","col3":"100 - 107","col4":"86 - 89"},{"id":"row4","order":3,"col1":"XL","col2":"92 - 99","col3":"108 - 114","col4":"91 - 94"},{"id":"row5","orde