<script>
  (() => {
    const productId = 10835846136146;
    const containerId = `gl-stock-delivery-${productId}`;
    const variantDataId = `gl-stock-variant-data-${productId}`;

    function initialiseGlStockDelivery() {
      const container = document.getElementById(containerId);
      const dataElement = document.getElementById(variantDataId);

      if (
        !container ||
        !dataElement ||
        container.dataset.initialised === 'true'
      ) {
        return;
      }

      container.dataset.initialised = 'true';

      let variants = [];

      try {
        variants = JSON.parse(dataElement.textContent);
      } catch (error) {
        console.warn('GL stock data could not be loaded.', error);
        return;
      }

      const statusText = container.querySelector(
        '.gl-stock-delivery__text'
      );

      const stockBar = container.querySelector(
        '.gl-stock-delivery__bar'
      );

      const stockProgress = container.querySelector(
        '.gl-stock-delivery__progress'
      );

      if (!statusText || !stockBar || !stockProgress) return;

      function getVariant(variantId) {
        return variants.find((variant) => {
          return String(variant.id) === String(variantId);
        });
      }

      function calculateStockPercentage(variantId) {
        const seed = `${productId}-${variantId}`;
        let hash = 0;

        for (let index = 0; index < seed.length; index++) {
          hash = ((hash << 5) - hash) + seed.charCodeAt(index);
          hash |= 0;
        }

        return 16 + (Math.abs(hash) % 23);
      }

      function updateStockBar(variantId) {
        const variant = getVariant(variantId);

        if (!variant) return;

        container.dataset.currentVariantId = String(variant.id);

        if (!variant.available) {
          container.classList.add('is-sold-out');
          statusText.textContent = 'Out of stock';
          stockProgress.style.width = '0%';
          stockBar.setAttribute('aria-valuenow', '0');
          return;
        }

        const percentage = calculateStockPercentage(variant.id);

        container.classList.remove('is-sold-out');
        statusText.textContent = 'Almost out of stock';
        stockProgress.style.width = `${percentage}%`;
        stockBar.setAttribute(
          'aria-valuenow',
          String(percentage)
        );
      }

      function getVariantIdFromUrl() {
        const parameters = new URLSearchParams(
          window.location.search
        );

        return parameters.get('variant');
      }

      function getVariantIdFromProductForm() {
        const productForms = document.querySelectorAll(
          'form[action*="/cart/add"]'
        );

        for (const form of productForms) {
          const variantInput = form.querySelector(
            'input[name="id"], select[name="id"]'
          );

          if (
            variantInput &&
            variantInput.value &&
            getVariant(variantInput.value)
          ) {
            return variantInput.value;
          }
        }

        return null;
      }

      function getCurrentVariantId() {
        return (
          getVariantIdFromUrl() ||
          getVariantIdFromProductForm() ||
          container.dataset.currentVariantId
        );
      }

      function refreshStockBar() {
        window.setTimeout(() => {
          const variantId = getCurrentVariantId();

          if (variantId) {
            updateStockBar(variantId);
          }
        }, 50);
      }

      updateStockBar(container.dataset.currentVariantId);

      document.addEventListener('change', (event) => {
        const target = event.target;

        if (
          target.matches(
            'input[type="radio"], input[name="id"], select'
          )
        ) {
          refreshStockBar();

          window.setTimeout(() => {
            const variantId = getCurrentVariantId();

            if (variantId) {
              updateStockBar(variantId);
            }
          }, 250);
        }
      });

      document.addEventListener('variant:change', (event) => {
        const selectedVariant =
          event.detail?.variant ||
          event.detail?.selectedVariant ||
          event.detail;

        if (selectedVariant?.id) {
          updateStockBar(selectedVariant.id);
        } else {
          refreshStockBar();
        }
      });

      let previousUrl = window.location.href;

      const observer = new MutationObserver(() => {
        if (window.location.href !== previousUrl) {
          previousUrl = window.location.href;
          refreshStockBar();
        }
      });

      observer.observe(document.documentElement, {
        childList: true,
        subtree: true
      });
    }

    initialiseGlStockDelivery();

    document.addEventListener(
      'shopify:section:load',
      initialiseGlStockDelivery
    );
  })();
